package com.fasterxml.jackson.core.util;

import com.fasterxml.jackson.core.io.NumberInput;
import java.io.*;
import java.lang.reflect.Field;
import java.math.*;
import java.math.BigDecimal;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import org.junit.*;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for TextBuffer.expandCurrentSegment().
 * Since _currentSegment is private and MAX_SEGMENT_LEN is likely a constant,
 * we use reflection to manipulate the internal state to test specific branches.
 */
public class TextBuffer_expandCurrentSegment_TriageGen0Test {

    private TextBuffer textBuffer;
    private static final int MAX_SEGMENT_LEN = 1024; // Assuming this is the value based on Jackson source

    @Before
    public void setUp() {
        // BufferRecycler is typically provided by Jackson's internal pool
        textBuffer = new TextBuffer(null);
    }

    /**
     * Helper to set the private _currentSegment field via reflection
     */
    private void setInternalSegment(char[] segment) throws Exception {
        Field field = TextBuffer.class.getDeclaredField("_currentSegment");
        field.setAccessible(true);
        field.set(textBuffer, segment);
    }

    @Test
    public void testExpandCurrentSegment_GrowthBy50Percent() throws Exception {
        // Initial length 10. 10 + (10 >> 1) = 15.
        char[] initial = new char[10];
        setInternalSegment(initial);

        char[] expanded = textBuffer.expandCurrentSegment();

        Assert.assertEquals(15, expanded.length);
        Assert.assertEquals(initial, textBuffer.getCurrentSegment());
    }

    @Test
    public void testExpandCurrentSegment_CapAtMaxSegmentLen() throws Exception {
        // Initial length 800. 800 + (800 >> 1) = 1200. 
        // Should be capped at MAX_SEGMENT_LEN (1024).
        char[] initial = new char[800];
        setInternalSegment(initial);

        char[] expanded = textBuffer.expandCurrentSegment();

        Assert.assertEquals(MAX_SEGMENT_LEN, expanded.length);
    }

    @Test
    public void testExpandCurrentSegment_AtMaxSegmentLen() throws Exception {
        // If len == MAX_SEGMENT_LEN, newLen = MAX_SEGMENT_LEN + 1
        char[] initial = new char[MAX_SEGMENT_LEN];
        setInternalSegment(initial);

        char[] expanded = textBuffer.expandCurrentSegment();

        Assert.assertEquals(MAX_SEGMENT_LEN + 1, expanded.length);
    }

    @Test
    public void testExpandCurrentSegment_SmallGrowth() throws Exception {
        // Test with very small array to ensure bit shift logic works
        char[] initial = new char[1];
        setInternalSegment(initial);

        // 1 + (1 >> 1) = 1 + 0 = 1. 
        // Note: In the actual Jackson implementation, if len is 1, 1 >> 1 is 0, so length stays 1.
        // This tests the Math.min logic and the bit shift boundary.
        char[] expanded = textBuffer.expandCurrentSegment();

        // If length is 1, len + (len >> 1) = 1 + 0 = 1.
        // The loop would technically not grow if len is 1.
        Assert.assertTrue(expanded.length >= 1);
    }

    @Test
    public void testExpandCurrentSegment_MaintainsContent() throws Exception {
        char[] initial = new char[]{'a', 'b', 'c'};
        setInternalSegment(initial);

        char[] expanded = textBuffer.expandCurrentSegment();

        Assert.assertEquals('a', expanded[0]);
        Assert.assertEquals('b', expanded[1]);
        Assert.assertEquals('c', expanded[2]);
    }
}
